describe('Async Data Fetching - Non-Blocking Initial Render', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should render initial page content before async data is fetched', () => {
    // Intercept the async data API call
    cy.intercept('GET', '/api/user-data', (req) => {
      req.reply((res) => {
        res.delay(1000);
        res.send({
          statusCode: 200,
          body: {
            id: 1,
            name: 'John Doe',
            email: 'john@example.com'
          }
        });
      });
    }).as('fetchUserData');

    // Verify initial page content is visible before API responds
    cy.get('[data-testid="initial-page-title"]').should('be.visible').should('contain', 'Dashboard');
    cy.get('[data-testid="loading-spinner"]').should('be.visible');
    cy.get('[data-testid="user-data-card"]').should('not.exist');

    // Wait for the async API call to complete
    cy.wait('@fetchUserData');

    // Verify async data is now displayed
    cy.get('[data-testid="loading-spinner"]').should('not.exist');
    cy.get('[data-testid="user-data-card"]').should('be.visible');
    cy.get('[data-testid="user-name"]').should('contain', 'John Doe');
    cy.get('[data-testid="user-email"]').should('contain', 'john@example.com');
  });

  it('should handle async data fetch failure without blocking initial render', () => {
    // Intercept the async data API call and simulate failure
    cy.intercept('GET', '/api/user-data', {
      statusCode: 500,
      body: {
        error: 'Internal Server Error'
      }
    }).as('fetchUserDataFailed');

    // Verify initial page content is still rendered
    cy.get('[data-testid="initial-page-title"]').should('be.visible').should('contain', 'Dashboard');
    cy.get('[data-testid="loading-spinner"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('not.exist');

    // Wait for the failed API call
    cy.wait('@fetchUserDataFailed');

    // Verify error state is displayed without blocking the page
    cy.get('[data-testid="loading-spinner"]').should('not.exist');
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Failed to load user data');
    cy.get('[data-testid="retry-button"]').should('be.visible');
    cy.get('[data-testid="user-data-card"]').should('not.exist');
  });
});
